const getDomain = (url: string) => {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return "";
  }
};

const isCitationLink = (href: string) => {
  try {
    const url = new URL(href);
    return url.protocol === "http:" || url.protocol === "https:";
  } catch {
    return false;
  }
};

const CitationBadge = ({ href }: { href: string }) => {
  const domain = getDomain(href);

  return (
    <a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      className="inline-flex items-center gap-1 rounded-xs bg-primary-hover px-0.5 h-lh text-xs text-ink-secondary no-underline transition-colors hover:bg-primary-hover hover:text-ink-primary"
    >
      <img
        src={`https://www.google.com/s2/favicons?domain=${domain}&sz=32`}
        alt=""
        width={12}
        height={12}
        className="shrink-0 rounded-full"
      />
      <span>{domain}</span>
    </a>
  );
};

const markdownComponents: Components = {
  a: ({ href, children, node, ...props }) => {
    if (href && isCitationLink(href)) {
      return <CitationBadge href={href} />;
    }

    return (
      <a href={href} {...props}>
        {children}
      </a>
    );
  },
};

