"use client";

import { splitReasoningByHeaders } from "@intentface/chat/message-utils";
import { Reasoning as ReasoningPrimitive, useReasoning } from "@intentface/chat/reasoning";
import { AnimatePresence, motion } from "motion/react";
import { type ComponentProps, memo, type ReactNode } from "react";
import { ChevronDownIcon } from "@/components/icons/chevron-down";
import { Markdown } from "@/components/ui/markdown";
import { cn } from "@/lib/utils";
import { BrainIcon } from "../icons/brain";
import { TextShimmer } from "../ui/text-shimmer";

export { useReasoning };

export type ReasoningRootProps = ComponentProps<typeof ReasoningPrimitive>;

const ReasoningRoot = memo(({ className, ...props }: ReasoningRootProps) => (
  <ReasoningPrimitive className={cn("not-prose w-full", className)} {...props} />
));

ReasoningRoot.displayName = "Reasoning";

export type ReasoningTriggerProps = ComponentProps<typeof ReasoningPrimitive.Trigger> & {
  label?: string[];
  getThinkingMessage?: (
    isStreaming: boolean,
    duration?: number,
    label?: string,
  ) => { key: string; component: ReactNode };
};

const defaultGetThinkingMessage = (
  isStreaming: boolean,
  duration?: number,
  label?: string,
): { key: string; component: ReactNode } => {
  if (isStreaming || duration === 0) {
    if (isStreaming && label) {
      return {
        key: `header-${label}`,
        component: <TextShimmer>{label}</TextShimmer>,
      };
    }
    return {
      key: "thinking",
      component: <TextShimmer>Thinking...</TextShimmer>,
    };
  }

  return {
    key: "thought",
    component: <span>Thought for {duration ?? "a few"} seconds</span>,
  };
};

const ReasoningTrigger = memo(
  ({
    label,
    getThinkingMessage = defaultGetThinkingMessage,
    className,
    children,
    ...props
  }: ReasoningTriggerProps) => {
    const { isStreaming, isOpen, duration } = useReasoning();
    const activeLabel = label?.at(-1);

    const { key, component } = getThinkingMessage(isStreaming, duration, activeLabel);
    return (
      <ReasoningPrimitive.Trigger
        className={cn(
          "flex cursor-pointer w-full text-sm items-center gap-2 text-ink-secondary rounded-md transition-colors hover:text-ink-primary",
          className,
        )}
        {...props}
      >
        {children ?? (
          <>
            <div className="flex items-center gap-1">
              <BrainIcon className="size-4" />
              <AnimatePresence mode="popLayout" initial={false}>
                <motion.span
                  key={key}
                  initial={{ opacity: 0, y: "100%", filter: "blur(4px)" }}
                  animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
                  exit={{ opacity: 0, y: "-100%", filter: "blur(4px)" }}
                  transition={{ duration: 0.3, ease: "easeOut" }}
                  className="whitespace-nowrap text-gray-11/60"
                >
                  {component}
                </motion.span>
              </AnimatePresence>
            </div>
            <ChevronDownIcon
              className={cn("size-5 transition-transform", isOpen ? "rotate-180" : "rotate-0")}
            />
          </>
        )}
      </ReasoningPrimitive.Trigger>
    );
  },
);

ReasoningTrigger.displayName = "ReasoningTrigger";

export type ReasoningContentProps = Omit<
  ComponentProps<typeof ReasoningPrimitive.Content>,
  "children"
> & {
  children: string | string[];
};

const ReasoningContent = ({ children, className, ...props }: ReasoningContentProps) => {
  const texts = Array.isArray(children) ? children : [children];
  const sections = splitReasoningByHeaders(texts);

  return (
    <ReasoningPrimitive.Content className={cn("text-sm", className)} {...props}>
      <div className="flex flex-col gap-3 p-2">
        {sections.map((section, i) => (
          <div key={i} className="flex flex-col gap-1">
            {section.header && (
              <span className="text-sm font-medium text-ink-primary">{section.header}</span>
            )}
            {section.body && (
              <Markdown className="text-ink-secondary text-sm [&_p]:mb-0">{section.body}</Markdown>
            )}
          </div>
        ))}
      </div>
    </ReasoningPrimitive.Content>
  );
};

export const Reasoning = Object.assign(ReasoningRoot, {
  Trigger: ReasoningTrigger,
  Content: ReasoningContent,
});

"use client";

import { StepQueue as StepQueuePrimitive, useStepQueue } from "@intentface/chat/step-queue";
import { AnimatePresence, motion } from "motion/react";
import { Children, type ComponentProps, type ReactNode } from "react";
import { TextShimmer } from "@/components/ui/text-shimmer";
import { cn } from "@/lib/utils";

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const ITEM_HEIGHT = 20; // h-5
const ITEM_GAP = 8; // gap-2
const MAX_VISIBLE = 5;
const MAX_HEIGHT = MAX_VISIBLE * ITEM_HEIGHT + (MAX_VISIBLE - 1) * ITEM_GAP;

// ---------------------------------------------------------------------------
// Root
//
// Always renders all children. The inner container animates height between one
// item (collapsed) and full content (expanded, capped). `justify-end` keeps
// the last item visible when collapsed. Open state comes from the primitive.
// ---------------------------------------------------------------------------

type StepQueueRootProps = ComponentProps<typeof StepQueuePrimitive>;

const StepQueueHeightContainer = ({ children }: { children: ReactNode }) => {
  const { isOpen } = useStepQueue();

  return (
    <div
      className="relative flex flex-col justify-end gap-2"
      style={{ maxHeight: MAX_HEIGHT, height: isOpen ? "auto" : ITEM_HEIGHT }}
    >
      <AnimatePresence mode="popLayout" initial={false}>
        {children}
      </AnimatePresence>
    </div>
  );
};

const StepQueueRoot = ({ className, children, ...props }: StepQueueRootProps) => {
  const shouldUseMask = Children.count(children) > 1;

  return (
    <StepQueuePrimitive
      className={cn(
        "not-prose relative w-full cursor-pointer p-3",
        shouldUseMask &&
          "mask-[linear-gradient(to_bottom,transparent,black_24px,black_calc(100%-24px),transparent)]",
        className,
      )}
      {...props}
    >
      <StepQueueHeightContainer>{children}</StepQueueHeightContainer>
    </StepQueuePrimitive>
  );
};

StepQueueRoot.displayName = "StepQueue";

// ---------------------------------------------------------------------------
// Item — animated wrapper for a single step
// ---------------------------------------------------------------------------

type StepQueueItemProps = ComponentProps<typeof motion.div>;

const StepQueueItem = ({ className, children, ...props }: StepQueueItemProps) => {
  return (
    <motion.div
      data-slot="step-queue-item"
      initial={{ height: 0 }}
      animate={{ height: ITEM_HEIGHT }}
      exit={{ height: 0 }}
      transition={{
        duration: 0.2,
        type: "spring",
        bounce: 0,
      }}
      className={cn("flex shrink-0 items-center text-sm font-medium text-ink-secondary", className)}
      {...props}
    >
      <motion.div
        initial={{ opacity: 0, y: ITEM_HEIGHT, filter: "blur(8px)" }}
        animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
        exit={{ opacity: 0, y: -ITEM_HEIGHT, filter: "blur(8px)" }}
        transition={{ duration: 0.2, type: "spring", bounce: 0 }}
        className="flex shrink-0 items-center gap-2"
      >
        {children}
      </motion.div>
    </motion.div>
  );
};

StepQueueItem.displayName = "StepQueueItem";

// ---------------------------------------------------------------------------
// Icon — renders inside an Item, swaps between a custom icon and a default
// ---------------------------------------------------------------------------

type StepQueueIconProps = ComponentProps<typeof StepQueuePrimitive.Icon>;

const StepQueueIcon = ({ className, ...props }: StepQueueIconProps) => (
  <StepQueuePrimitive.Icon
    className={cn("flex shrink-0 items-center justify-center", className)}
    {...props}
  />
);

StepQueueIcon.displayName = "StepQueueIcon";

// ---------------------------------------------------------------------------
// Label — text content inside an Item, shimmer when active
// ---------------------------------------------------------------------------

type StepQueueLabelProps = ComponentProps<typeof StepQueuePrimitive.Label>;

const StepQueueLabel = ({ active = false, className, children, ...props }: StepQueueLabelProps) => (
  <StepQueuePrimitive.Label
    active={active}
    className={cn("min-w-0 flex-1 truncate", className)}
    {...props}
  >
    {active ? <TextShimmer>{children}</TextShimmer> : children}
  </StepQueuePrimitive.Label>
);

StepQueueLabel.displayName = "StepQueueLabel";

// ---------------------------------------------------------------------------
// Compound export
// ---------------------------------------------------------------------------

export const StepQueue = Object.assign(StepQueueRoot, {
  Item: StepQueueItem,
  Icon: StepQueueIcon,
  Label: StepQueueLabel,
});

"use client";

import { useState } from "react";
import { Composer } from "@/components/ai/composer";
import { Message } from "@/components/ai/message";
import { Thread } from "@/components/ai/thread";

type DemoMessage = {
  id: string;
  role: "user" | "assistant";
  text: string;
};

export const IntentfaceChatDemo = () => {
  const [messages, setMessages] = useState<DemoMessage[]>([
    {
      id: "welcome",
      role: "assistant",
      text: "Ask a question to try the installed Intentface chat primitives.",
    },
  ]);

  return (
    <div className="h-[640px] rounded-lg border border-primary-border bg-secondary">
      <Thread>
        <Thread.Overlay direction="top" />
        <Thread.Viewport>
          {messages.map((message, index) => (
            <Message
              key={message.id}
              role={message.role}
              isLast={index === messages.length - 1}
              isError={false}
            >
              <Message.Content>
                {message.role === "user" ? (
                  <Message.Text>{message.text}</Message.Text>
                ) : (
                  <Message.Markdown>{message.text}</Message.Markdown>
                )}
              </Message.Content>
            </Message>
          ))}
        </Thread.Viewport>
        <Thread.Composer>
          <Composer
            onSubmit={(data) => {
              if (data.kind !== "message") return;
              setMessages((current) => [
                ...current,
                {
                  id: crypto.randomUUID(),
                  role: "user",
                  text: data.text,
                },
                {
                  id: crypto.randomUUID(),
                  role: "assistant",
                  text: "This demo only echoes the UI flow. Wire `Composer` to your AI SDK chat handler for streaming responses.",
                },
              ]);
            }}
          >
            <Composer.Container>
              <Composer.Textarea>
                <Composer.Placeholder placeholder="Message Intentface..." />
              </Composer.Textarea>
              <Composer.Actions>
                <Composer.Submit />
              </Composer.Actions>
            </Composer.Container>
          </Composer>
        </Thread.Composer>
        <Thread.ScrollButton />
      </Thread>
    </div>
  );
};
